import { CustomTypography } from "../materials/Typography";

import List from '@mui/material/List';
import ListItem from '@mui/material/ListItem';
import ListItemAvatar from '@mui/material/ListItemAvatar';
import ListItemButton from '@mui/material/ListItemButton';
import ListItemText from '@mui/material/ListItemText';
import DialogTitle from '@mui/material/DialogTitle';
import Dialog from '@mui/material/Dialog';
import PersonIcon from '@mui/icons-material/Person';
import AddIcon from '@mui/icons-material/Add';
import FolderIcon from '@mui/icons-material/Folder';
import { blue } from '@mui/material/colors';
import IconButton from '@mui/material/IconButton';
import DeleteIcon from '@mui/icons-material/Delete';
import { Avatar } from "@mantine/core/lib/components/Avatar/Avatar";

import EmailIcon from '@mui/icons-material/Email';
import PhoneIcon from '@mui/icons-material/Phone';
import SwitchAccessShortcutAdd from "@mui/icons-material/SwitchAccessShortcutAdd";
import LinkedInIcon from '@mui/icons-material/LinkedIn';

export default function Contact() {

  return (
    <>
      <List dense={false}>
        <ListItem
            secondaryAction={
                <IconButton edge="end" aria-label="delete">
                    <SwitchAccessShortcutAdd />
                </IconButton>
            }
        >
            <ListItemAvatar>
                <a href="https://www.flaticon.com/free-icons/gmail" title="gmail icons"></a>
                <EmailIcon sx={{ color: 'salmon' }}/>
            </ListItemAvatar>
            <ListItemText
                primary="Email" 
                secondary={true ? 'aidanwigmore4@gmail.com' : null}
            />
        </ListItem>
        <ListItem
            secondaryAction={
            <IconButton edge="end" aria-label="delete">
                <SwitchAccessShortcutAdd />
            </IconButton>
            }
        >
            <ListItemAvatar>
                <PhoneIcon />
            </ListItemAvatar>
            <ListItemText
                primary="Cell Phone" 
                secondary={true ? '(555) 123-4567' : null}
            />
        </ListItem>
        <ListItem
            secondaryAction={
                <IconButton 
                    edge="end" 
                    aria-label="delete" 
                    component="a" 
                    href="https://www.linkedin.com/in/aidan-wigmore" 
                    target="_blank" 
                    rel="noopener noreferrer"
                >
                    <SwitchAccessShortcutAdd />
                </IconButton>
            }
        >
            <ListItemAvatar>
                <LinkedInIcon sx={{ color: blue[500] }}/>
            </ListItemAvatar>
            <ListItemText
                primary="LinkedIn" 
                secondary={true ? 'linkedin.com/in/aidanwigmore' : null}
            />
        </ListItem>
    </List>
    </>
  )
}
